"""One-use source preparation; no main/DNS writes or private attachments."""
from pathlib import Path
import json
root=Path('.')
assert json.loads(Path('release.json').read_text())['release']=='2026-10-15.1'
old='2026-10-15.1';new='2026-10-15.2'
for p in root.glob('*.html'):p.write_text(p.read_text().replace(old,new))
p=Path('release.json');d=json.loads(p.read_text());d['release']=new;p.write_text(json.dumps(d,indent=2)+'\n')
def replace(path,old,new):
 p=Path(path);s=p.read_text();assert old in s,(path,old[:60]);p.write_text(s.replace(old,new))
replace('index.html','<a class="btn" href="contact.html">Contact</a>','<a class="btn" href="Daeho-Lee-CV.pdf" type="application/pdf">CV <span>(PDF)</span></a>')
replace('index.html','A current CV is available on request.','Public CV · October 2026 · 2 pages.')
replace('index.html','      <li><span class="year">2023</span>','      <li><span class="year">2024</span><span class="what"><strong>Certificate of Commendation</strong>, Chief of Staff, Republic of Korea Army.</span></li>\n      <li><span class="year">2023</span>')
replace('index.html','<span class="year">2013–19</span>','<span class="year">2013–20</span>')
replace('contact.html','Research questions, collaboration, and CV requests are all welcome.','Research questions and collaboration inquiries are welcome.')
replace('contact.html','<ul class="links-list">','<ul class="links-list">\n        <li><a href="Daeho-Lee-CV.pdf" type="application/pdf">Curriculum vitae (PDF, 2 pages)</a></li>')
replace('research.html','Against an air‑bladder pressure reference, the distance‑based method starts stance just before physical contact, so it reports a shorter swing phase (by 3.6 and 5.9 percentage points for the left and right foot); in exchange, it keeps measuring through swing [J1].','Compared with air‑bladder pressure measurements, the distance‑based method reported swing fractions 3.6 and 5.9 percentage points lower for the left and right foot, respectively (Table 2). It also provided distance measurements during swing [J1].')
replace('research.html','The heel leaves and reaches the ground before the MTP in every step, and the two distances cross when the sole is parallel to the ground; the six phases are defined from these events. The VL53L1X sensor is not accurate below 40&nbsp;mm, so near the ground its reading is used only as a contact flag, with thresholds under 10&nbsp;mm. To keep the decision real‑time, the algorithm compares each reading with the previous one instead of differentiating the distance signal, which would amplify noise and require a phase‑lagging filter [J1].','The algorithm defines six gait states from heel and forefoot contact flags, the relative sensor distances, and whether the heel distance is increasing or decreasing. After subtracting the standing offset from each distance signal, small thresholds were used for contact-state detection rather than precise near-ground ranging. During swing, successive heel readings were compared without explicitly estimating velocity [J1, Sections 3.2 and 4.2].')
replace('research.html','Figures reproduced from [J1], © Korean Society for Precision Engineering, under CC BY‑NC 3.0.','Figures 2, 8, and 10 from D. Lee, <a href="https://doi.org/10.7736/JKSPE.026.00011">“Real-time Gait Phase Detection System Using Non-contact Distance Sensors”</a>, JKSPE (2026). © Korean Society for Precision Engineering. <a href="https://creativecommons.org/licenses/by-nc/3.0/" rel="license">CC BY‑NC 3.0</a>; converted to WebP for display.')
replace('MAINTAINING.md','- Retain [T1] provenance on the three figures. New display assets use lossless conversion and exactly-white exterior trim only; media-processing.json records source hashes, crop boxes and pixel checks. Source assets remain unmodified.','- The old T1 display decision was superseded by owner-approved PR #8: show the published J1 figures with their original figure numbers and license; retain the presentation-to-journal relationship in text. Do not restore the supplied slide deck or private abstract in public assets without new authorization.')
replace('MAINTAINING.md',"- Home timeline carries CV honors (CYBATHLON medals, KAIST Global Leadership Award, magna cum laude, scholarships). The 2024 ROK Army commendation and any ADD role description wait for the owner's confirmation of ADD release approval.",'- Home timeline carries CV honors and the owner-authorized 2024 Certificate of Commendation from the Chief of Staff, Republic of Korea Army. Do not infer its project, technical grounds, or a new job title. Approval of the award text does not approve additional ADD work descriptions.')
replace('MAINTAINING.md','CV v0.99: AFN','CV v0.991: AFN')
p=Path('MAINTAINING.md');p.write_text(p.read_text()+'''\n## Public CV intake
- The website PDF is `Daeho-Lee-CV.pdf`; its exact release metadata and digest are in `public-cv.json`. Only the owner-designated public edition is eligible. Never substitute the full CV.
- Before linking a new PDF, remove previous saved revisions and unreferenced objects, then check rendered pages, extracted text, links, embedded files, and remaining objects. Visible redaction alone is not a file-level clearance check.
- The current reviewed PDF preserves the supplied public edition’s visible text, including its temporary work-summary labels. Publishing it is not a certification of employer clearance or final application readiness.
- The expected PDF must pass `check_public_cv.py` before this change is ready for merge. Keep revision-recovery demonstrations and private document findings outside this repository.
''')
Path('public-cv.json').write_text(json.dumps({'path':'Daeho-Lee-CV.pdf','version':'v0.991-public','updated':'2026-10','pages':2,'bytes':139285,'sha256':'aa723e5fe1705667e8d98e4e765e90ffb33f4dd02e4cb66cf8fefdbc2f65e6ec','note':'Owner-designated public edition; work-summary fields remain marked pending. Visible content preserved.'},indent=2)+'\n')
